package ai.decisionos.aside;
import android.app.job.*;import android.content.*;import org.json.*;import java.util.*;
/** Durable home/deadline -> bot question -> Qwen -> same conversation. One queue, stable request IDs. */
public final class ChatWork extends JobService {
 static final int JOB=8822;volatile boolean stopped;
 static void schedule(Context c){if(c.getSystemService(JobScheduler.class).getPendingJob(JOB)!=null)return;c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(JOB,new ComponentName(c,ChatWork.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(500).setPersisted(true).build());}
 static String enqueue(Context c,String id){String conversation="";try(ScheduledWorkStore s=new ScheduledWorkStore(c);GoalStore g=new GoalStore(c)){JSONObject r=s.get(id);if(r.optString("id").isEmpty())return "";g.goal(r.optString("goal_id"));conversation=r.optString("conversation_id");if(BuildConfig.HOME_STYLE==6&&r.optString("room_type").isEmpty()){JSONObject room=GroupRooms.room(c);conversation=room.optString("id");s.metadata(id,"conversation_id",conversation);s.metadata(id,"room_type","group");s.metadata(id,"group_goals",room.optJSONObject("goals").toString());r=s.get(id);}if(conversation.isEmpty()){conversation=g.defaultConversation(r.optString("goal_id")).optString("id");s.metadata(id,"conversation_id",conversation);}if(!r.optString("room_type").equals("group")&&!g.workspaceRow("conversations",conversation).optString("goalId").equals(r.optString("goal_id")))return "";String state=r.optString("state");if(state.equals("SCHEDULED")||state.equals("READY")){if(s.state(id,state,"CHAT_QUEUED","자동봇이 대화방에 요청했어요. 담당 누비가 시작할게요.")){s.metadata(id,"request_id",id);r=s.get(id);append(c,r,"user",r.optString("prompt"),"running",null);append(c,r,"assistant","요청을 받았어. 필요한 정보를 확인하고 여기서 이어서 처리할게.","running",null);}}schedule(c);ScheduledWork.notify(c,s.get(id));}catch(Exception e){android.util.Log.e("NubiChatWork","enqueue failed: "+e.getClass().getSimpleName());}return conversation;}
 static void append(Context c,JSONObject work,String role,String text,String state,JSONObject result){if(work.optString("room_type").equals("group")){if(role.equals("assistant"))GroupRooms.append(c,work,result);return;}try(GoalStore g=new GoalStore(c)){android.database.sqlite.SQLiteDatabase db=g.getWritableDatabase();db.beginTransaction();try{JSONObject row=g.workspaceRow("conversations",work.optString("conversation_id"));if(!row.optString("goalId").equals(work.optString("goal_id")))throw new IllegalArgumentException();JSONArray messages=row.optJSONArray("messages");if(messages==null)messages=new JSONArray();String mid="scheduled-"+work.optString("id")+"-"+role;JSONObject m=null;for(int i=0;i<messages.length();i++)if(mid.equals(messages.optJSONObject(i).optString("id")))m=messages.optJSONObject(i);if(m==null){m=new JSONObject();GoalStore.put(m,"id",mid);GoalStore.put(m,"at",System.currentTimeMillis());messages.put(m);}GoalStore.put(m,"scheduledWorkId",work.optString("id"));GoalStore.put(m,"role",role);GoalStore.put(m,"text",text);GoalStore.put(m,"state",state);if(result!=null){if(result.optLong("expires_at")>0)GoalStore.put(m,"expiresAt",result.optLong("expires_at"));GoalStore.put(m,"steps",result.optJSONArray("progress"));JSONObject document=result.optJSONObject("document");if(document!=null){GoalStore.put(document,"job_id",work.optString("job_id"));GoalStore.put(document,"goalId",work.optString("goal_id"));GoalStore.put(m,"document",document);}}GoalStore.put(row,"messages",messages);g.saveWorkspace("conversations",row);c.getSharedPreferences("nubi_chat_work",0).edit().putLong("revision",System.currentTimeMillis()).commit();db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 static boolean busy(Context c){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){for(JSONObject r:s.list())if(r.optString("state").equals("CHAT_RUNNING"))return true;}return false;}
 @Override public boolean onStartJob(JobParameters params){stopped=false;new Thread(()->{boolean retry=false;long end=System.currentTimeMillis()+100000;try(ScheduledWorkStore s=new ScheduledWorkStore(this);GoalStore g=new GoalStore(this)){ChatWorkTransport transport=new ChatWorkTransport(this);for(JSONObject r:s.list()){if(stopped||System.currentTimeMillis()>end){retry=true;break;}String state=r.optString("state");if(!state.equals("CHAT_QUEUED")&&!state.equals("CHAT_RUNNING"))continue;boolean occupied=false;for(JSONObject run:g.workspace("runs",null))if(!run.optBoolean("legacy")&&RunCoordinator.live(run.optString("state")))occupied=true;if(occupied){retry=true;break;}String id=r.optString("id");try{if(r.optString("room_type").equals("group")){runGroup(s,r,transport,end);if(s.get(id).optString("state").equals("CHAT_RUNNING"))retry=true;continue;}g.goal(r.optString("goal_id"));if(state.equals("CHAT_QUEUED")){if(!s.state(id,state,"CHAT_RUNNING","담당 누비가 대화방에서 작업 중이에요"))continue;}while(!stopped&&System.currentTimeMillis()<end){r=s.get(id);JSONObject body=new JSONObject(),answer;String job=r.optString("job_id");if(job.isEmpty()){GoalStore.put(body,"goal_id",r.optString("goal_id"));GoalStore.put(body,"character",g.goal(r.optString("goal_id")).optString("character"));GoalStore.put(body,"task",r.optString("prompt"));GoalStore.put(body,"request_id",id);answer=transport.post("/chat-submit",body);}else{GoalStore.put(body,"job_id",job);answer=transport.post("/chat-status",body);}if(!r.optString("goal_id").equals(answer.optString("goal_id"))||!id.equals(answer.optString("request_id"))||(!job.isEmpty()&&!job.equals(answer.optString("job_id"))))throw new java.io.IOException("response owner mismatch");if(answer.optString("job_id").isEmpty())throw new java.io.IOException("missing job id");s.metadata(id,"job_id",answer.optString("job_id"));r=s.get(id);String status=answer.optString("state");if(Arrays.asList("completed","failed","cancelled").contains(status)){String text=status.equals("completed")?answer.optString("answer"):answer.optString("error","작업이 중단됐어. 대화에서 다시 요청해 줘.");append(this,r,"user",r.optString("prompt"),status,null);append(this,r,"assistant",text,status,answer);s.state(id,"CHAT_RUNNING",status.equals("completed")?"RESULT_READY":"FAILED",status.equals("completed")?"대화방에 처리 결과가 도착했어요":"대화방에서 실패 원인을 확인해 주세요");ScheduledWork.notify(this,s.get(id));break;}JSONArray progress=answer.optJSONArray("progress");String detail=progress!=null&&progress.length()>0?progress.optString(progress.length()-1):"필요한 정보를 확인하고 있어.";append(this,r,"assistant",detail,"running",answer);Thread.sleep(1800);}if(s.get(id).optString("state").equals("CHAT_RUNNING"))retry=true;}catch(Exception e){s.state(id,"CHAT_RUNNING","CHAT_RUNNING","연결 결과 확인 중 · 같은 요청 ID로 재확인해요");retry=true;break;}}}catch(Exception e){retry=true;}if(!stopped)jobFinished(params,retry);},"nubi-chat-work").start();return true;}
 void runGroup(ScheduledWorkStore s,JSONObject r,ChatWorkTransport transport,long end)throws Exception{String id=r.optString("id");if(r.optString("state").equals("CHAT_QUEUED")&&!s.state(id,"CHAT_QUEUED","CHAT_RUNNING","누비와 친구들이 작업 중이에요"))return;while(!stopped&&System.currentTimeMillis()<end){r=s.get(id);JSONObject body=new JSONObject();String job=r.optString("job_id");JSONObject answer;if(job.isEmpty()){GoalStore.put(body,"request_id",id);GoalStore.put(body,"text",r.optString("prompt")+(r.optString("repeat_rule").isEmpty()?"":"\n반복 작업의 이번 실행 대상 날짜: "+java.time.Instant.ofEpochMilli(r.optLong("due_at")).atZone(ChatTime.SEOUL).toLocalDate()+". 이번 날짜의 자료를 조회하고 다음 예약을 새로 만들지는 마."));GoalStore.put(body,"history",new JSONArray());GoalStore.put(body,"goals",new JSONObject(r.optString("group_goals")));answer=transport.post("/group-submit",body);}else{GoalStore.put(body,"job_id",job);answer=transport.post("/group-status",body);}if(!id.equals(answer.optString("request_id"))||answer.optString("job_id").isEmpty()||(!job.isEmpty()&&!job.equals(answer.optString("job_id"))))throw new java.io.IOException("group response owner mismatch");s.metadata(id,"job_id",answer.optString("job_id"));r=s.get(id);GroupRooms.append(this,r,answer);String state=answer.optString("state");if(Arrays.asList("completed","failed","cancelled").contains(state)){s.state(id,"CHAT_RUNNING",state.equals("completed")?"RESULT_READY":"FAILED",state.equals("completed")?"누비와 친구들에 결과가 도착했어요":answer.optString("error","실행 결과 확인 필요"));ScheduledWork.notify(this,s.get(id));return;}Thread.sleep(1800);}}
 @Override public boolean onStopJob(JobParameters p){stopped=true;return true;}
}
